-- MahaDevan's OS — Hyprland default configuration (Lua).
--
-- Hyprland 0.57 loads hyprland.lua, not hyprland.conf: a .conf from an older
-- release is silently ignored and the compositor generates its own config (the
-- "autogenerated config" banner). Installed as /etc/xdg/hypr/hyprland.lua and
-- copied into /etc/skel/.config/hypr/hyprland.lua for new accounts.
--
-- Syntax reference: /usr/share/hypr/hyprland.lua (shipped by the hyprland
-- package) and the stubs in /usr/share/hypr/stubs/hl.meta.lua.

---------------------
----  MONITORS   ----
---------------------

hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "1",
})

-----------------------------
----  ENVIRONMENT VARS   ----
-----------------------------

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")

-----------------------
----  LOOK & FEEL  ----
-----------------------

hl.config({
    general = {
        gaps_in      = 4,
        gaps_out     = 8,
        border_size  = 2,
        col = {
            active_border   = { colors = { "rgba(23ebd1ee)", "rgba(1b6b7aee)" }, angle = 45 },
            inactive_border = "rgba(2a3644aa)",
        },
        resize_on_border = true,
        layout           = "dwindle",
    },

    decoration = {
        rounding         = 8,
        active_opacity   = 1.0,
        inactive_opacity = 0.96,
        blur = {
            enabled = true,
            size    = 4,
            passes  = 2,
        },
        shadow = {
            enabled      = true,
            range        = 12,
            render_power = 3,
            color        = "rgba(00000055)",
        },
    },

    animations = {
        enabled = true,
    },

    dwindle = {
        preserve_split = true,
    },

    misc = {
        force_default_wallpaper  = 0,
        disable_hyprland_logo    = true,
        disable_splash_rendering = true,
        focus_on_activate        = true,
    },
})

hl.curve("easeOut", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.0 } } })

hl.animation({ leaf = "global",     enabled = true, speed = 4, bezier = "easeOut" })
hl.animation({ leaf = "windows",    enabled = true, speed = 4, bezier = "easeOut" })
hl.animation({ leaf = "fade",       enabled = true, speed = 4, bezier = "easeOut" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 4, bezier = "easeOut", style = "slide" })

---------------
---- INPUT ----
---------------

hl.config({
    input = {
        kb_layout   = "us",
        kb_variant  = "",
        kb_model    = "",
        kb_options  = "",
        follow_mouse = 1,
        sensitivity  = 0,
        touchpad = {
            natural_scroll        = true,
            tap_to_click          = true,
            disable_while_typing  = true,
            clickfinger_behavior  = true,
        },
    },
})

hl.gesture({
    fingers   = 3,
    direction = "horizontal",
    action    = "workspace",
})

--------------------
---- KEYBINDS   ----
--------------------

local mod      = "SUPER"
local terminal = "kitty"
local menu     = "wofi --show drun"

hl.bind(mod .. " + Q",      hl.dsp.exec_cmd(terminal))
hl.bind(mod .. " + Return", hl.dsp.exec_cmd(terminal))
hl.bind(mod .. " + D",      hl.dsp.exec_cmd(menu))
hl.bind(mod .. " + E",      hl.dsp.exec_cmd("dolphin"))

hl.bind(mod .. " + C",      hl.dsp.window.close())
hl.bind(mod .. " + SHIFT + Q", hl.dsp.exit())
hl.bind(mod .. " + F",      hl.dsp.window.fullscreen())
hl.bind(mod .. " + Space",  hl.dsp.window.float({ action = "toggle" }))
hl.bind(mod .. " + P",      hl.dsp.window.pseudo())
hl.bind(mod .. " + J",      hl.dsp.layout("togglesplit"))

hl.bind(mod .. " + left",   hl.dsp.focus({ direction = "left" }))
hl.bind(mod .. " + right",  hl.dsp.focus({ direction = "right" }))
hl.bind(mod .. " + up",     hl.dsp.focus({ direction = "up" }))
hl.bind(mod .. " + down",   hl.dsp.focus({ direction = "down" }))

hl.bind(mod .. " + SHIFT + left",  hl.dsp.window.move({ direction = "left" }))
hl.bind(mod .. " + SHIFT + right", hl.dsp.window.move({ direction = "right" }))
hl.bind(mod .. " + SHIFT + up",    hl.dsp.window.move({ direction = "up" }))
hl.bind(mod .. " + SHIFT + down",  hl.dsp.window.move({ direction = "down" }))

for i = 1, 10 do
    local key = i % 10
    hl.bind(mod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind(mod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

hl.bind(mod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))
hl.bind(mod .. " + mouse:272",  hl.dsp.window.drag(),   { mouse = true })
hl.bind(mod .. " + mouse:273",  hl.dsp.window.resize(), { mouse = true })

hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1.4 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),        { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),       { locked = true, repeating = true })
hl.bind("XF86AudioPlay",        hl.dsp.exec_cmd("playerctl play-pause"),                             { locked = true })
hl.bind("XF86AudioNext",        hl.dsp.exec_cmd("playerctl next"),                                   { locked = true })
hl.bind("XF86AudioPrev",        hl.dsp.exec_cmd("playerctl previous"),                               { locked = true })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl set +5%"),                            { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl set 5%-"),                           { locked = true, repeating = true })

hl.bind(mod .. " + SHIFT + S", hl.dsp.exec_cmd("grim -g \"$(slurp)\" - | wl-copy"))
hl.bind(mod .. " + PRINT",     hl.dsp.exec_cmd("grim - | wl-copy"))
hl.bind(mod .. " + SHIFT + L", hl.dsp.exec_cmd("loginctl lock-session"))

--------------------
---- AUTOSTART   ----
--------------------

-- A missing binary is harmless: Hyprland ignores the failed exec.
hl.on("hyprland.start", function()
    hl.exec_cmd("dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP")
    hl.exec_cmd("/usr/lib/polkit-kde-authentication-agent-1")
    hl.exec_cmd("hyprpolkitagent")
    hl.exec_cmd("nm-applet --indicator")
    hl.exec_cmd("blueman-applet")
    hl.exec_cmd("swaybg -i /usr/share/backgrounds/mahadevanos/wallpaper.png -m fill")
end)

------------------------
---- LAYER RULES   ----
------------------------

hl.layer_rule({ name = "wofi-blur", match = { namespace = "wofi" } })
